1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    /* Dark enough to keep 3:1 against --bg at the resting 0.85 opacity */
31	    [data-color="green"] { --fg: #15803d; }
32	    [data-color="amber"] { --fg: #b45309; }
33	    [data-color="violet"] { --fg: #7c3aed; }
34	    [data-color="cyan"] { --fg: #0e7490; }
35	    @media (prefers-color-scheme: dark) {
36	      :root {
37	        --bg: #111;
38	        --text: #d1d5db;
39	        --fg: #93c5fd;
40	        --shadow: rgba(0, 0, 0, 0.6);
41	        --kbd-bg: rgba(255, 255, 255, 0.15);
42	      }
43	      [data-color="red"] { --fg: #fca5a5; }
44	      [data-color="green"] { --fg: #86efac; }
45	      [data-color="amber"] { --fg: #fcd34d; }
46	      [data-color="violet"] { --fg: #c4b5fd; }
47	      [data-color="cyan"] { --fg: #67e8f9; }
48	    }
49	    @media (prefers-contrast: more) {
50	      :root {
51	        --shadow: rgba(0, 0, 0, 0.9);
52	        --drop: drop-shadow(0 2px 8px var(--shadow));
53	      }
54	      .circle svg {
55	        opacity: 1;
56	      }
57	    }
58	    @media (forced-colors: active) {
59	      /* The color is the content here, so keep it; the stroke guarantees the shape */
60	      .circle svg {
61	        forced-color-adjust: none;
62	        color: var(--fg);
63	      }
64	      svg circle {
65	        stroke: CanvasText;
66	        stroke-width: 2;
67	      }
68	    }
69	    body {
70	      min-height: 100vh;
71	      min-height: 100dvh;
72	      display: grid;
73	      place-items: center;
74	      padding: 1rem;
75	      background: var(--bg);
76	      color: var(--text);
77	      font-family: system-ui, -apple-system, sans-serif;
78	    }
79	    main {
80	      width: 100%;
81	      display: flex;
82	      flex-direction: column;
83	      align-items: center;
84	      text-align: center;
85	    }
86	    .circle {
87	      display: block;
88	      width: min(360px, 100%, 60vh);
89	      aspect-ratio: 1;
90	      border: 0;
91	      border-radius: 50%;
92	      background: none;
93	      color: var(--fg);
94	      cursor: pointer;
95	      touch-action: manipulation;
96	      -webkit-tap-highlight-color: transparent;
97	      /* Shift+click and double-click would otherwise select the text below */
98	      -webkit-user-select: none;
99	      user-select: none;
100	      -webkit-touch-callout: none;
101	      transition: color 0.4s ease;
102	      min-height: 48px;
103	      min-width: 48px;
104	    }
105	    .no-transition,
106	    .no-transition svg {
107	      transition: none !important;
108	    }
109	    .circle:focus-visible {
110	      outline: 3px solid currentColor;
111	      outline-offset: 12px;
112	    }
113	    svg {
114	      display: block;
115	      width: 100%;
116	      height: 100%;
117	      overflow: visible;
118	      opacity: 0.85;
119	      filter: var(--drop);
120	      transition: opacity 0.3s ease;
121	    }
122	    .circle:active svg,
123	    .circle:focus-visible svg {
124	      opacity: 1;
125	    }
126	    @keyframes pulse {
127	      0% {
128	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
129	      }
130	      100% {
131	        filter: var(--drop) drop-shadow(0 0 0 transparent);
132	      }
133	    }
134	    @media (hover: hover) {
135	      .circle:hover svg {
136	        opacity: 1;
137	      }
138	    }
139	    @media (prefers-reduced-motion: no-preference) {
140	      svg {
141	        transition:
142	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
143	          opacity 0.3s ease;
144	      }
145	      .circle:focus-visible svg {
146	        transform: scale(1.05);
147	      }
148	      .circle:active svg {
149	        transform: scale(0.97);
150	      }
151	      .circle.color-changed svg {
152	        animation: pulse 0.5s ease-out;
153	      }
154	    }
155	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
156	      .circle:hover:not(:active) svg {
157	        transform: scale(1.05);
158	      }
159	    }
160	    .visually-hidden {
161	      position: absolute;
162	      width: 1px;
163	      height: 1px;
164	      overflow: hidden;
165	      clip-path: inset(50%);
166	      white-space: nowrap;
167	    }
168	    .status {
169	      margin-top: 2rem;
170	      font-weight: 600;
171	    }
172	    .hint {
173	      margin-top: 0.25rem;
174	      font-size: 0.875rem;
175	      line-height: 1.75;
176	      text-wrap: balance;
177	    }
178	    .help-button {
179	      margin-left: 0.5rem;
180	      display: inline-block;
181	      width: 1.5rem;
182	      height: 1.5rem;
183	      border-radius: 50%;
184	      background: var(--kbd-bg);
185	      border: 1px solid var(--text);
186	      color: var(--text);
187	      cursor: pointer;
188	      font: inherit;
189	      font-size: 0.75rem;
190	      font-weight: bold;
191	      line-height: 1;
192	      text-align: center;
193	      vertical-align: middle;
194	      touch-action: manipulation;
195	      transition: background-color 0.2s ease, color 0.2s ease;
196	    }
197	    .help-button:focus-visible {
198	      outline: 2px solid currentColor;
199	      outline-offset: 2px;
200	    }
201	    @media (hover: hover) {
202	      /* Not currentColor: it would resolve to the hover color and hide the "?" */
203	      .help-button:hover {
204	        background: var(--text);
205	        color: var(--bg);
206	      }
207	    }
208	    .keys {
209	      display: none;
210	    }
211	    .keys.visible {
212	      display: inline;
213	    }
214	    @media (hover: none) and (pointer: coarse) {
215	      .hint .keys {
216	        display: none !important;
217	      }
218	      .help-button {
219	        display: none;
220	      }
221	    }
222	    kbd {
223	      display: inline-block;
224	      padding: 0.125rem 0.375rem;
225	      background: var(--kbd-bg);
226	      border: 1px solid transparent;
227	      border-radius: 0.25rem;
228	      font-family: monospace;
229	      font-size: 0.75em;
230	      line-height: 1.2;
231	    }
232	  </style>
233	</head>
234	<body>
235	  <main>
236	    <h1 class="visually-hidden">Animated Circle</h1>
237	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
238	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
239	        <circle cx="50" cy="50" r="50" fill="currentColor" stroke="none"/>
240	      </svg>
241	    </button>
242	    <p class="status" id="status" role="status">Blue</p>
243	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> or hold to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
244	    <noscript><p class="hint">JavaScript is required to change the color.</p></noscript>
245	  </main>
246	  <script>
247	    const config = {
248	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
249	      storageKey: 'circle-color',
250	      hapticDuration: 50,
251	      longPressDuration: 500,
252	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
253	    };
254	
255	    const DOM = {
256	      button: document.querySelector('.circle'),
257	      status: document.querySelector('.status'),
258	      helpButton: document.querySelector('.help-button'),
259	      keyHint: document.querySelector('.keys'),
260	      verbSpan: document.querySelector('.hint .verb'),
261	      doubleVerbSpan: document.querySelector('.hint .double-verb'),
262	    };
263	
264	    const state = {
265	      index: 0,
266	      shiftHeld: false,
267	      hoverCapable: true,
268	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
269	      hoverQuery: matchMedia('(hover: none)'),
270	      longPressTimer: null,
271	      longPressed: false,
272	      pointerType: '',
273	    };
274	
275	    function loadColor() {
276	      try {
277	        return localStorage.getItem(config.storageKey);
278	      } catch {
279	        return null;
280	      }
281	    }
282	
283	    function saveColor(color) {
284	      try {
285	        localStorage.setItem(config.storageKey, color);
286	      } catch {}
287	    }
288	
289	    function applyColor() {
290	      const color = config.colors[state.index];
291	      DOM.button.dataset.color = color === 'blue' ? '' : color;
292	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
293	    }
294	
295	    function syncFromStorage(color = loadColor()) {
296	      const index = config.colors.indexOf(color);
297	      state.index = index === -1 ? 0 : index;
298	      applyColor();
299	    }
300	
301	    function setIndex(next, { haptic = false } = {}) {
302	      if (next === state.index) return;
303	      state.index = next;
304	      applyColor();
305	      saveColor(config.colors[state.index]);
306	
307	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
308	
309	      if (state.reducedMotion.matches) return;
310	      DOM.button.classList.remove('color-changed');
311	      void DOM.button.offsetWidth;
312	      DOM.button.classList.add('color-changed');
313	    }
314	
315	    function changeColor(step) {
316	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
317	    }
318	
319	    function updateDeviceVerbs() {
320	      state.hoverCapable = !state.hoverQuery.matches;
321	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
322	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
323	    }
324	
325	    function toggleKeyHintVisibility() {
326	      const expanded = DOM.keyHint.classList.toggle('visible');
327	      DOM.helpButton.setAttribute('aria-expanded', expanded);
328	    }
329	
330	    function syncKeyHint() {
331	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
332	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
333	    }
334	
335	    function handleKeyDown(event) {
336	      if (event.key === 'Enter' || event.key === ' ') {
337	        if (!event.repeat) state.shiftHeld = event.shiftKey;
338	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
339	        return;
340	      }
341	
342	      if (event.altKey || event.ctrlKey || event.metaKey) return;
343	
344	      if (event.key in config.keySteps) {
345	        event.preventDefault();
346	        changeColor(config.keySteps[event.key]);
347	      } else if (event.key === 'Home') {
348	        event.preventDefault();
349	        setIndex(0, { haptic: true });
350	      } else if (event.key === 'End') {
351	        event.preventDefault();
352	        setIndex(config.colors.length - 1, { haptic: true });
353	      }
354	    }
355	
356	    function handleEscape(event) {
357	      if (event.key !== 'Escape' || state.hoverCapable) return;
358	      if (DOM.keyHint.classList.contains('visible')) toggleKeyHintVisibility();
359	    }
360	
361	    // Initialize
362	    syncFromStorage();
363	
364	    requestAnimationFrame(() => requestAnimationFrame(() => {
365	      DOM.button.classList.remove('no-transition');
366	    }));
367	
368	    updateDeviceVerbs();
369	    syncKeyHint();
370	    // e.g. a tablet gaining or losing a trackpad/keyboard
371	    state.hoverQuery.addEventListener('change', () => {
372	      updateDeviceVerbs();
373	      syncKeyHint();
374	    });
375	
376	    // Event listeners
377	    function clearLongPressTimer() {
378	      if (state.longPressTimer) clearTimeout(state.longPressTimer);
379	      state.longPressTimer = null;
380	    }
381	
382	    DOM.button.addEventListener('keydown', handleKeyDown);
383	    DOM.button.addEventListener('keyup', (event) => {
384	      if (event.key === ' ') state.shiftHeld = event.shiftKey;
385	    });
386	    DOM.button.addEventListener('blur', () => {
387	      state.shiftHeld = false;
388	      clearLongPressTimer();
389	    });
390	    DOM.button.addEventListener('pointerdown', (event) => {
391	      clearLongPressTimer();
392	      state.longPressed = false;
393	      state.pointerType = event.pointerType;
394	      if (!event.isPrimary || event.button !== 0) return;
395	      state.longPressTimer = setTimeout(() => {
396	        state.longPressTimer = null;
397	        state.longPressed = true;
398	        // Still confirm the gesture when already reset, since the release click is swallowed
399	        if (state.index === 0 && navigator.vibrate) navigator.vibrate(config.hapticDuration);
400	        setIndex(0, { haptic: true });
401	      }, config.longPressDuration);
402	    });
403	    // Android fires contextmenu on a touch hold, racing the long-press reset
404	    DOM.button.addEventListener('contextmenu', (event) => {
405	      if (state.pointerType === 'mouse') {
406	        // Ctrl+click on macOS is a primary-button press that opens the menu,
407	        // and no pointerup follows to stop the timer
408	        clearLongPressTimer();
409	      } else if (state.longPressTimer || state.longPressed) {
410	        event.preventDefault();
411	      }
412	    });
413	    DOM.button.addEventListener('pointerup', clearLongPressTimer);
414	    DOM.button.addEventListener('pointercancel', clearLongPressTimer);
415	    DOM.button.addEventListener('pointerleave', clearLongPressTimer);
416	    DOM.button.addEventListener('click', (event) => {
417	      clearLongPressTimer();
418	      // Releasing a long press still fires a click, which would undo the reset.
419	      // Keyboard clicks (detail 0) are never part of a long press.
420	      const afterLongPress = state.longPressed && event.detail !== 0;
421	      state.longPressed = false;
422	      if (afterLongPress || event.detail > 1) return;
423	      changeColor(event.shiftKey || state.shiftHeld ? -1 : 1);
424	      state.shiftHeld = false;
425	    });
426	    DOM.button.addEventListener('dblclick', (event) => {
427	      event.preventDefault();
428	      setIndex(0);
429	    });
430	    DOM.button.addEventListener('animationend', () => {
431	      DOM.button.classList.remove('color-changed');
432	    });
433	
434	    DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
435	    // On the document so it also works from the help button that opened the hint
436	    addEventListener('keydown', handleEscape);
437	
438	    addEventListener('storage', (event) => {
439	      if (event.key !== config.storageKey && event.key !== null) return;
440	      syncFromStorage(event.newValue);
441	    });
442	    // Storage events are not delivered while the page sits in the bfcache
443	    addEventListener('pageshow', (event) => {
444	      if (event.persisted) syncFromStorage();
445	    });
446	  </script>
447	</body>
448	</html>
